// Get or create session
const sessionId = $json.sessionId || 'guest-' + Date.now();

// Get conversation history
const history = $getWorkflowStaticData('user').get(sessionId) || [];

// Add current message
history.push({
  role: 'user',
  message: $json.message,
  timestamp: new Date().toISOString()
});

// Keep last 6 messages
if (history.length > 6) {
  history.splice(0, history.length - 6);
}

// Save history
$getWorkflowStaticData('user').set(sessionId, history);

// Prepare context
const recentConversation = history
  .slice(-3)
  .map(msg => `${msg.role}: ${msg.message}`)
  .join('
');

// Get user info if available
const userInfo = $json.userInfo || {};

return {
  sessionId,
  message: $json.message,
  history: recentConversation,
  userInfo,
  pageUrl: $json.pageUrl || 'unknown',
  timestamp: new Date().toISOString()
};

// System prompt for Econutri chatbot
const systemPrompt = `You are "Econutri AI Assistant", an expert in nutrition and organic health products.

STORE INFORMATION:
- Name: Econutri Organic Store
- Products: Organic foods, supplements, health kits
- Services: Free health consultations, personalized nutrition plans
- Key Products: Organic honey, Herbal teas, Multivitamins, Fitness trackers

INSTRUCTIONS:
1. NATURAL CONVERSATION: Be friendly, empathetic, conversational
2. PRODUCT RECOMMENDATIONS: Suggest specific products with benefits
3. HEALTH ADVICE: Provide practical, evidence-based tips
4. COMPARISONS: Compare products objectively
5. PERSONALIZATION: Use available user context
6. SAFETY: Always recommend consulting doctors for medical advice

CONTEXT:
Previous conversation:
${$json.history}

User information: ${JSON.stringify($json.userInfo)}
Current page: ${$json.pageUrl}

RESPONSE FORMAT:
- Keep responses concise (2-4 sentences)
- Use bullet points when listing products
- Include product names and key benefits
- Ask follow-up questions to understand needs better
- End with a helpful question or suggestion

Now respond to this message:`;

// Combine with user message
const fullPrompt = `${systemPrompt}

User: ${$json.message}

Assistant:`;

return {
  prompt: fullPrompt,
  sessionId: $json.sessionId,
  originalMessage: $json.message
};

// Extract response from Gemini
const geminiResponse = $json.candidates[0].content.parts[0].text;

// Add to conversation history
const sessionId = $input.first().json.sessionId;
const history = $getWorkflowStaticData('user').get(sessionId) || [];

history.push({
  role: 'assistant',
  message: geminiResponse,
  timestamp: new Date().toISOString()
});

// Save updated history
$getWorkflowStaticData('user').set(sessionId, history);

// Prepare final response
return {
  reply: geminiResponse,
  sessionId: sessionId,
  timestamp: new Date().toLocaleTimeString(),
  features: {
    natural_conversation: true,
    personalized: $input.first().json.userInfo ? true : false,
    contains_recommendations: geminiResponse.toLowerCase().includes('product') || geminiResponse.toLowerCase().includes('recommend'),
    contains_advice: geminiResponse.toLowerCase().includes('advice') || geminiResponse.toLowerCase().includes('tip')
  }
};

// Fallback response if Gemini fails
return {
  reply: "I'm having trouble connecting right now. I can help you with:\n• Product recommendations\n• Health management tips\n• Form question explanations\n\nWhat would you like to know about?",
  sessionId: $input.first().json.sessionId,
  fallback: true
};
